declare namespace SigApi {
    interface Language {
        readonly languageIndex: number
        readonly languageID: number
        readonly languageCode: string
        readonly description: string
        readonly imageSource: string
        readonly name: string
        /**
         * Returns the index of the Language in the Runtime
         * 
         * @returns {number} the index of the language
         */
        getIndex(): number
        /**
         * Returns the LanguageID
         * 
         * @returns {number} The 4 digits language id
         */
        getId(): number
        /**
         * Returns the LanguageCode
         * 
         * @returns {string} The language Code
         */
        getCode(): string
        /**
         * Returns the description of the Language
         * 
         * @returns {string} The description
         */
        getDescription(): string
        /**
         * @deprecated
         * Returns the path to an images which was downloaded with the Language
         * replaced by getFullImageSrc because result of getImageSrc is incomplete
         * 
         * @returns {string} path to the image
         */
        getImageSrc(): string | undefined
        /**
         * Returns the path to an images which was downloaded with the Language
         * 
         * @returns {string} path to the image
         */
        getFullImageSrc(): string | undefined
    }
}
